function rememberDraft(value){try{if(value.text)localStorage.setItem(DRAFT_RECOVERY_KEY,JSON.stringify(value));else localStorage.removeItem(DRAFT_RECOVERY_KEY)}catch{}}
function Mark(){return <svg className="mark" viewBox="0 0 90 60" fill="none" aria-hidden="true"><path fill="currentColor" d="M3 46C19 40 30 29 44 35C36 39 40 44 50 46C62 50 72 43 87 45C62 48 60 58 38 51C24 46 19 43 3 46Z"/><path d="M43 39C58 29 53 9 62 5M48 43C59 36 64 31 69 22" stroke="currentColor" strokeWidth="1.5"/><ellipse cx="63" cy="5" rx="3" ry="5" transform="rotate(35 63 5)" fill="currentColor"/><ellipse cx="70" cy="21" rx="2.6" ry="4" transform="rotate(35 70 21)" fill="currentColor"/></svg>}
function SourceLinks({output,onOpen}){if(!output?.evidence?.length)return null;return <InfoDetails className="source-disclosure" Icon={Link2Icon} label={`参照メモ · ${output.evidence.length}`}><div className="native-sources">{output?.evidence?.map(e=><button key={e.revisionId} onClick={()=>onOpen(e.noteId)}><Link2Icon/><span>{e.text.slice(0,90)}{e.text.length>90?'…':''}</span><small>{e.valid?(sourceLabels[e.sourceKind]||'メモ').toUpperCase():'以前の版'}</small></button>)}</div></InfoDetails>}
function Rating({output,onRate}){
  const [reason,setReason]=useState(output?.rating?.rating==='bad'?output.rating.reason||'':'');
  const [comment,setComment]=useState(output?.rating?.rating==='bad'?output.rating.comment||'':'');
  useEffect(()=>{setReason(output?.rating?.rating==='bad'?output.rating.reason||'':'');setComment(output?.rating?.rating==='bad'?output.rating.comment||'':'')},[output?.id,output?.rating?.rating,output?.rating?.reason,output?.rating?.comment]);
  if(!output)return null;
  const sameBad=output.rating?.rating==='bad'&&output.rating.reason===reason&&(output.rating.comment||'')===comment;
  return <div className="native-rating" role="group" aria-label="回答の評価"><button className={output.rating?.rating==='good'?'on':''} aria-pressed={output.rating?.rating==='good'} onClick={()=>onRate(output,output.rating?.rating==='good'?'clear':'good','','')}><CheckIcon/>役に立った</button><button className={output.rating?.rating==='bad'?'on bad':''} aria-pressed={output.rating?.rating==='bad'} onClick={()=>onRate(output,sameBad?'clear':'bad',sameBad?'':reason,sameBad?'':comment)}><Cross2Icon/>{output.rating?.rating==='bad'&&!sameBad?'評価を更新':'合わない'}</button>{output.rating?.rating==='bad'&&<><select value={reason} onChange={e=>setReason(e.target.value)} aria-label="合わない理由"><option value="">理由（任意）</option><option value="incorrect">内容が違う</option><option value="not-my-taste">好みと違う</option><option value="not-now">今は必要ない</option><option value="too-vague">曖昧すぎる</option><option value="repeated">前にも見た</option></select>{reason==='incorrect'&&<input className="native-correction" value={comment} onChange={e=>setComment(e.target.value)} maxLength={500} placeholder="訂正を書く（任意）" aria-label="訂正"/>}</>}</div>
}
