function Activity({label}){return <div className="ai-activity" role="status"><span className="ai-activity-mark" aria-hidden="true"><i/><i/><i/></span><span>{label}</span><span className="ai-activity-track" aria-hidden="true"/></div>}
function trapCaptureFocus(event){
  if(event.key!=='Tab')return;
  const items=[...event.currentTarget.querySelectorAll('button:not(:disabled),textarea:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),a[href]')].filter(item=>item.getClientRects().length);
  if(!items.length)return;
  const first=items[0],last=items[items.length-1];
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
}
function SavedImage({attachment}){
  const [src,setSrc]=useState('');
  useEffect(()=>{let current=true;api.readAttachment(attachment.id).then(data=>{if(current)setSrc(`data:${data.mediaType};base64,${data.dataBase64}`)}).catch(()=>{});return()=>{current=false}},[attachment.id]);
  return src?<img src={src} alt={attachment.fileName||'Attached image'}/>:<span className="image-loading">Loading image…</span>;
}
function NoteCard({note,selected,saved,index=0,onSelect}){
  const hasImage=note.attachments?.length>0;
  const Icon=hasImage?ImageIcon:FileTextIcon;
  const kind=note.isDemo?'サンプル':note.originKind==='generated'?'提案の下書き':sourceLabels[note.sourceKind]||'メモ';
  return <button data-note-id={note.id} className={'note-row note-card'+(selected?' selected':'')+(saved?' just-saved':'')} style={{'--card-delay':`${Math.min(index,6)*45}ms`}} onClick={()=>onSelect(note.id)} aria-pressed={selected}>
    <span className="note-card-head"><span className="note-card-kind"><Icon/>{kind}</span><time>{new Date(note.date).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</time></span>
    <span className="note-card-body"><span className="note-card-text">{note.text||'画像のメモ'}</span>{hasImage&&<span className="note-card-thumbnail"><SavedImage attachment={note.attachments[0]}/></span>}</span>
    {note.articleStatus==='ready'&&note.articleTitle&&<span className="note-card-article"><span>{note.articleSiteName||'記事'}</span><strong>{note.articleTitle}</strong></span>}
    <span className="note-card-foot"><span>{note.aiExcluded?<><LockClosedIcon/>AI対象外</>:hasImage?`画像 ${note.attachments.length}枚`:null}</span><ArrowRightIcon/></span>
  </button>;
}
function ArticlePreview({note,onOpen,onRetry}){
  if(!note.sourceUrl)return null;
  const ready=note.articleStatus==='ready';
  return <section className="inspector-article" aria-label="記事プレビュー">
    <span className="eyebrow">参考記事</span>
    {ready?<><h3>{note.articleTitle||note.articleSiteName||'記事'}</h3>{note.articleDescription&&<p>{note.articleDescription}</p>}<small>{note.articleSiteName}</small></>:<p>{note.articleStatus==='failed'?'プレビューを取得できませんでした':note.articleStatus==='pending'||note.articleStatus==='running'?'記事を読み込み中…':'リンクを保存済み'}</p>}
    <div><button type="button" className="secondary" onClick={()=>onOpen(note.id)}><Link2Icon/>記事を開く</button>{note.articleStatus==='failed'&&<button type="button" className="text-button" onClick={()=>onRetry(note.id)}><ReloadIcon/>再取得</button>}</div>
  </section>;
}
function ManagedBackups({items,loading,error,onRefresh,onDelete,headingId}){
  return <section className="managed-backups" aria-labelledby={headingId}><div className="managed-backups-head"><div>{!headingId&&<h3>アプリ内バックアップ</h3>}<InfoDetails label="対象ファイル"><p>取り込みや復元の前にpureが作成したファイルです。手動で保存したバックアップは含まれません。</p><p>別の場所に保存・コピーしたファイルはここから確認・削除できません。</p></InfoDetails></div><button className="text-button" onClick={onRefresh} disabled={loading}><ReloadIcon/>再確認</button></div>
    {loading?<p role="status">バックアップを確認中…</p>:error?<p role="alert">{error}</p>:items.length?<div className="managed-backup-list">{items.map(item=><div className="managed-backup-row" key={item.name}><div><strong>{item.name}</strong><small>{new Date(item.modifiedAt).toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric'})} · {Math.ceil(item.size/1024)} KB</small><span className={item.status==='contains-deleted'?'managed-backup-warning':''}>{item.status==='contains-deleted'?`完全削除したメモが${item.deletedCount}件残っています`:item.status==='unreadable'?'ファイルを確認できませんでした':'削除済みメモなし'}</span></div><button className="text-button" onClick={()=>onDelete(item.name)}><TrashIcon/>ファイルを削除</button></div>)}</div>:<p>アプリ内バックアップはありません。</p>}

  </section>;
}
